package org.freecad.mobilelab;
import java.io.IOException;
import java.util.*;
import org.json.*;
/** Small persistent exact-CAD feature DAG. All mutations run inside the engine transaction. */
final class FeatureModel {
    static JSONArray recipes=new JSONArray();
    static final Set<String> KINDS=new HashSet<>(Arrays.asList("Union","Cut","Intersect","Fillet","Extrude solid","Extrude surface","Revolve solid","Revolve surface","Loft solid","Loft surface","Sweep solid","Sweep surface","Pipe along curve","Section","Offset curve","Offset shape","Chamfer","Heal CAD","Sew surfaces","Hollow top","Solidify shell","Join curves","Planar region","Trim curve","Extend line","Project curve","Selected fillet","Selected chamfer","Selected shell","Trim patch","Untrim patch"));
    static void validate(JSONArray a,Set<Integer> alive)throws Exception{
        if(a.length()>250)throw new IOException("Feature history exceeds 250 operations");Map<Integer,JSONObject> outputs=new HashMap<>();
        for(int i=0;i<a.length();i++){JSONObject f=a.getJSONObject(i);int out=f.getInt("output");String kind=f.getString("kind");JSONArray ins=f.getJSONArray("inputs"),p=f.getJSONArray("params");if(out<1||outputs.put(out,f)!=null||!KINDS.contains(kind)||ins.length()<1||ins.length()>8||p.length()>16||(alive!=null&&!alive.contains(out)))throw new IOException("Invalid feature record");int np=p.length(),ni=ins.length();
            int expected=kind.startsWith("Extrude ")?3:kind.startsWith("Revolve ")||kind.equals("Section")?7:kind.equals("Trim patch")?4:kind.equals("Trim curve")||kind.equals("Extend line")?2:kind.equals("Union")||kind.equals("Cut")||kind.equals("Intersect")||kind.startsWith("Sweep ")||kind.equals("Join curves")||kind.equals("Planar region")||kind.equals("Solidify shell")||kind.equals("Untrim patch")?0:1;
            if(kind.startsWith("Selected ")){if(np<2)throw new IOException("Missing selected topology indices");}else if(np!=expected)throw new IOException("Wrong feature parameter count");
            if(kind.equals("Union")||kind.equals("Cut")||kind.equals("Intersect")||kind.startsWith("Sweep ")){if(ni!=2)throw new IOException("Feature needs two inputs");}else if(kind.startsWith("Loft ")||kind.equals("Join curves")||kind.equals("Sew surfaces")){if(ni<2)throw new IOException("Feature needs at least two inputs");}else if(ni!=1)throw new IOException("Feature needs one input");
            Set<Integer> used=new HashSet<>();for(int j=0;j<ins.length();j++){int id=ins.getInt(j);if(id<1||id==out||!used.add(id)||(alive!=null&&!alive.contains(id)))throw new IOException("Missing or repeated feature input");}for(int j=0;j<p.length();j++)if(!Double.isFinite(p.getDouble(j))||Math.abs(p.getDouble(j))>1000000)throw new IOException("Invalid feature parameter");if(kind.startsWith("Selected ")&&(ins.length()!=1||f.optString("topology").length()>500000||f.optString("topology").isEmpty()))throw new IOException("Selected topology signature is missing");}
        Set<Integer> visiting=new HashSet<>(),done=new HashSet<>();for(int id:outputs.keySet())visit(id,outputs,visiting,done);
    }
    private static void visit(int id,Map<Integer,JSONObject> m,Set<Integer> active,Set<Integer> done)throws Exception{if(done.contains(id)||!m.containsKey(id))return;if(!active.add(id))throw new IOException("Feature dependency cycle");JSONArray in=m.get(id).getJSONArray("inputs");for(int j=0;j<in.length();j++)visit(in.getInt(j),m,active,done);active.remove(id);done.add(id);}
    static void load(JSONArray a)throws Exception{if(a==null)a=new JSONArray();validate(a,null);recipes=new JSONArray(a.toString());}
    static JSONObject recipe(int id)throws Exception{for(int i=0;i<recipes.length();i++)if(recipes.getJSONObject(i).getInt("output")==id)return recipes.getJSONObject(i);return null;}
    static void detach(int id)throws Exception{JSONArray next=new JSONArray();for(int i=0;i<recipes.length();i++)if(recipes.getJSONObject(i).getInt("output")!=id)next.put(recipes.getJSONObject(i));recipes=next;}
    static int record(int output,String kind,int[] inputs,double[] p)throws Exception{if(!KINDS.contains(kind))return output;if(recipes.length()>=250)throw new IOException("Feature limit reached");JSONObject f=new JSONObject().put("output",output).put("kind",kind).put("inputs",new JSONArray(inputs)).put("params",new JSONArray(p));if(kind.startsWith("Selected "))f.put("topology",NativeCad.topology(inputs[0]));recipes.put(f);validate(recipes,null);return output;}
    static int model(String kind,int[] inputs,double[] p)throws Exception{return record(NativeCad.model(kind,inputs,p),kind,inputs,p);}
    static int operation(String kind,int a,int b,double amount)throws Exception{return record(NativeCad.operation(kind,a,b,amount),kind,kind.equals("Fillet")?new int[]{a}:new int[]{a,b},kind.equals("Fillet")?new double[]{amount}:new double[0]);}
    static void rebuild(JSONObject f)throws Exception{JSONArray in=f.getJSONArray("inputs"),pa=f.getJSONArray("params");int[] ids=new int[in.length()];double[] p=new double[pa.length()];for(int i=0;i<ids.length;i++)ids[i]=in.getInt(i);for(int i=0;i<p.length;i++)p[i]=pa.getDouble(i);if(f.getString("kind").startsWith("Selected ")&&!NativeCad.topology(ids[0]).equals(f.getString("topology")))throw new IOException("Selected edges/faces changed. Undo this edit, or detach and recreate feature #"+f.getInt("output")+" with a fresh selection.");NativeCad.rebuild(f.getInt("output"),f.getString("kind"),ids,p);}
    static void recompute(int changed)throws Exception{
        Set<Integer> affected=new HashSet<>();affected.add(changed);Set<Integer> pending=new HashSet<>();boolean expanded;
        do{expanded=false;for(int i=0;i<recipes.length();i++){JSONObject f=recipes.getJSONObject(i);int id=f.getInt("output");JSONArray in=f.getJSONArray("inputs");for(int j=0;j<in.length();j++)if(affected.contains(in.getInt(j))&&affected.add(id)){pending.add(id);expanded=true;break;}}}while(expanded);
        while(!pending.isEmpty()){boolean progress=false;for(int i=0;i<recipes.length();i++){JSONObject f=recipes.getJSONObject(i);int id=f.getInt("output");if(!pending.contains(id))continue;JSONArray in=f.getJSONArray("inputs");boolean ready=true;for(int j=0;j<in.length();j++)if(pending.contains(in.getInt(j)))ready=false;if(ready){rebuild(f);pending.remove(id);progress=true;}}if(!progress)throw new IOException("Feature recompute cycle");}
    }
    static void edit(int id,double[] p)throws Exception{NativeCad.edit(id,p);detach(id);recompute(id);}
    static void move(int id,double x,double y,double z)throws Exception{NativeCad.move(id,x,y,z);detach(id);recompute(id);}
    static void rotate(int id,double x,double y,double z)throws Exception{NativeCad.rotate(id,x,y,z);detach(id);recompute(id);}
    static void scale(int id,double factor)throws Exception{NativeCad.scale(id,factor);detach(id);recompute(id);}
    static int curve(String kind,double[] p,boolean closed,int replace)throws Exception{int id=NativeCad.curve(kind,p,closed,replace);if(replace>0){detach(id);recompute(id);}return id;}
    static void surfacePole(int id,double[] p)throws Exception{NativeCad.surfacePole(id,p);detach(id);recompute(id);}
    static void remove(int id)throws Exception{for(int i=0;i<recipes.length();i++){JSONArray in=recipes.getJSONObject(i).getJSONArray("inputs");for(int j=0;j<in.length();j++)if(in.getInt(j)==id)throw new IOException("Object is used by feature #"+recipes.getJSONObject(i).getInt("output")+". Detach or delete the dependent feature first.");}NativeCad.remove(id);detach(id);}
    static void independent(int[] ids)throws Exception{Set<Integer> chosen=new HashSet<>();for(int id:ids)chosen.add(id);for(int id:ids){Set<Integer> seen=new HashSet<>();ArrayDeque<Integer> queue=new ArrayDeque<>();queue.add(id);while(!queue.isEmpty()){JSONObject r=recipe(queue.remove());if(r==null)continue;JSONArray in=r.getJSONArray("inputs");for(int i=0;i<in.length();i++){int parent=in.getInt(i);if(chosen.contains(parent))throw new IOException("Batch transforms need independent roots. Detach derived outputs before selecting them with their inputs.");if(seen.add(parent))queue.add(parent);}}}}
    static void removeMany(int[] ids)throws Exception{Set<Integer> pending=new LinkedHashSet<>();for(int id:ids)pending.add(id);while(!pending.isEmpty()){boolean progress=false;for(int id:new ArrayList<Integer>(pending)){boolean leaf=true;for(int i=0;i<recipes.length();i++){JSONObject r=recipes.getJSONObject(i);JSONArray in=r.getJSONArray("inputs");for(int j=0;j<in.length();j++)if(in.getInt(j)==id){if(!pending.contains(r.getInt("output")))throw new IOException("A feature outside the selection still uses #"+id);leaf=false;}}if(leaf){remove(id);pending.remove(id);progress=true;}}if(!progress)throw new IOException("Dependent selection cannot be deleted");}}
    static void parameters(int id,double[] p)throws Exception{JSONObject f=recipe(id);if(f==null)throw new IOException("This object has no editable feature recipe");f.put("params",new JSONArray(p));rebuild(f);recompute(id);}
    static JSONArray remap(JSONArray a,Map<Integer,Integer> map)throws Exception{JSONArray result=new JSONArray();for(int i=0;a!=null&&i<a.length();i++){JSONObject f=new JSONObject(a.getJSONObject(i).toString());f.put("output",map.get(f.getInt("output")));JSONArray old=f.getJSONArray("inputs"),in=new JSONArray();for(int j=0;j<old.length();j++)in.put(map.get(old.getInt(j)));f.put("inputs",in);result.put(f);}return result;}
}
